import assert from "node:assert/strict";
import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import test from "node:test";
import {
  buildCards,
  buildDeck,
  CARD_BLUEPRINTS,
  decodeCardSource,
  discoverSourceFiles,
  extractFileContext,
} from "./deck.mjs";
import { dueCards, scheduleReview, summarizeDeck } from "./scheduler.mjs";

async function withFixture(run) {
  const root = await mkdtemp(path.join(tmpdir(), "improvedcodex-deck-"));
  try {
    await writeFile(path.join(root, "README.md"), "# Demo\n\n## First rule\n", "utf8");
    await mkdir(path.join(root, "code"));
    await writeFile(
      path.join(root, "code", "sample.js"),
      "export function calculate() {}\n",
      "utf8",
    );
    await mkdir(path.join(root, "spaced-repetition"));
    await writeFile(path.join(root, "spaced-repetition", "ignored.md"), "# Ignore\n", "utf8");
    await run(root);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

test("discovers source files but excludes the repetition engine", async () => {
  await withFixture(async root => {
    const relative = (await discoverSourceFiles(root)).map(file => path.relative(root, file));
    assert.deepEqual(relative.sort(), [path.join("code", "sample.js"), "README.md"].sort());
  });
});

test("extracts Markdown headings and code symbols as contextual cues", async () => {
  await withFixture(async root => {
    const markdown = await extractFileContext(root, path.join(root, "README.md"));
    const code = await extractFileContext(root, path.join(root, "code", "sample.js"));
    assert.equal(markdown.title, "Demo");
    assert.ok(markdown.cues.includes("First rule"));
    assert.ok(code.cues.includes("calculate"));
  });
});

test("builds exactly ten distinct cards for every file", async () => {
  await withFixture(async root => {
    const cards = await buildDeck(root);
    assert.equal(CARD_BLUEPRINTS.length, 10);
    assert.equal(cards.length, 20);
    assert.equal(new Set(cards.map(card => card.id)).size, 20);
    for (const source of ["README.md", "code/sample.js"]) {
      assert.equal(cards.filter(card => card.source === source).length, 10);
    }
  });
});

test("card IDs preserve stable source identity", () => {
  const cards = buildCards([
    {
      relativePath: "folder/lesson.md",
      title: "Lesson",
      cues: ["Lesson", "Rule"],
      kind: "md",
    },
  ]);
  assert.equal(decodeCardSource(cards[0].id), "folder/lesson.md");
});

test("new and expired cards are due while future cards are not", () => {
  const cards = [{ id: "new" }, { id: "past" }, { id: "future" }];
  const reviews = {
    past: { due: "2026-01-01T00:00:00.000Z" },
    future: { due: "2027-01-01T00:00:00.000Z" },
  };
  assert.deepEqual(
    dueCards(cards, reviews, new Date("2026-06-01T00:00:00.000Z")).map(card => card.id),
    ["new", "past"],
  );
});

test("good reviews follow widening 2, 7, and 30 day spacing", () => {
  const now = new Date("2026-01-01T00:00:00.000Z");
  const first = scheduleReview(undefined, "good", now);
  const second = scheduleReview(first, "good", now);
  const third = scheduleReview(second, "good", now);
  assert.equal(first.intervalDays, 2);
  assert.equal(second.intervalDays, 7);
  assert.equal(third.intervalDays, 30);
});

test("again schedules a quick retry and increments lapses", () => {
  const now = new Date("2026-01-01T00:00:00.000Z");
  const result = scheduleReview({ stage: 3, reviews: 2, lapses: 1 }, "again", now);
  assert.equal(result.stage, 2);
  assert.equal(result.lapses, 2);
  assert.equal(result.due, "2026-01-01T00:10:00.000Z");
});

test("deck summary separates unseen, reviewed, learned, due, and lapses", () => {
  const cards = [{ id: "a" }, { id: "b" }];
  const reviews = {
    a: { stage: 3, due: "2027-01-01T00:00:00.000Z", lapses: 2 },
  };
  assert.deepEqual(summarizeDeck(cards, reviews, new Date("2026-01-01T00:00:00.000Z")), {
    total: 2,
    due: 1,
    unseen: 1,
    reviewed: 1,
    learned: 1,
    lapses: 2,
  });
});

test("invalid ratings and dates fail clearly", () => {
  assert.throws(() => scheduleReview(undefined, "maybe"), /Rating must be one of/);
  assert.throws(() => scheduleReview(undefined, "good", "not-a-date"), /Invalid date/);
});
